#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(tensor.dtype() == torch::kBFloat16,
                name, " must be bfloat16, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry for the Gemma3 fused gate + up
// projection with GELU-tanh chain. Per definition.json:
//   x         : [B, S, hidden_size = 3072]            bf16
//   gate_proj : [intermediate_size = 24576, hidden_size = 3072] bf16
//   up_proj   : [intermediate_size = 24576, hidden_size = 3072] bf16
//   output    : [B, S, intermediate_size = 24576]     bf16 (DPS)
//
// Algorithm (mirroring the PyTorch reference):
//   gate_output    = torch.matmul(x, gate_proj.t())
//   up_output      = torch.matmul(x, up_proj.t())
//   gate_fp32      = gate_output.to(fp32)
//   inner          = sqrt(2/pi) * (gate_fp32 + 0.044715 * gate_fp32**3)
//   activated_gate = 0.5 * gate_fp32 * (1 + tanh(inner))
//   activated_gate = activated_gate.to(bf16)   # bf16 downcast
//   output         = activated_gate * up_output   # bf16 multiply
//
// Const axes pinned by definition.json AND enforced on every tensor
// the kernel indexes with that fixed assumption:
//   hidden_size       = 3072
//   intermediate_size = 24576
void run(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor output
) {
    check_bf16_contiguous_cuda(x, "x");
    check_bf16_contiguous_cuda(gate_proj, "gate_proj");
    check_bf16_contiguous_cuda(up_proj, "up_proj");
    check_bf16_contiguous_cuda(output, "output");

    constexpr int64_t kHiddenSize = 3072;
    constexpr int64_t kIntermediateSize = 24576;

    TORCH_CHECK(x.dim() == 3,
                "x must be 3D [B, S, hidden_size]");
    TORCH_CHECK(gate_proj.dim() == 2,
                "gate_proj must be 2D [intermediate_size, hidden_size]");
    TORCH_CHECK(up_proj.dim() == 2,
                "up_proj must be 2D [intermediate_size, hidden_size]");
    TORCH_CHECK(output.dim() == 3,
                "output must be 3D [B, S, intermediate_size]");

    TORCH_CHECK(x.size(2) == kHiddenSize,
                "x.size(2) must equal hidden_size=3072, got ",
                x.size(2));
    TORCH_CHECK(gate_proj.size(0) == kIntermediateSize,
                "gate_proj.size(0) must equal intermediate_size=24576");
    TORCH_CHECK(gate_proj.size(1) == kHiddenSize,
                "gate_proj.size(1) must equal hidden_size=3072");
    TORCH_CHECK(up_proj.size(0) == kIntermediateSize,
                "up_proj.size(0) must equal intermediate_size=24576");
    TORCH_CHECK(up_proj.size(1) == kHiddenSize,
                "up_proj.size(1) must equal hidden_size=3072");
    TORCH_CHECK(output.size(0) == x.size(0),
                "output.size(0) must equal x.size(0)");
    TORCH_CHECK(output.size(1) == x.size(1),
                "output.size(1) must equal x.size(1)");
    TORCH_CHECK(output.size(2) == kIntermediateSize,
                "output.size(2) must equal intermediate_size=24576");

    // bf16 cuBLAS GEMMs via at::matmul. cuBLAS dispatches a bf16
    // GEMM using Sm80 bf16 tensor cores with fp32 accumulator. The
    // reference also uses torch.matmul for these projections, so
    // the cuBLAS path matches exactly.
    auto gate_output = at::matmul(x, gate_proj.t());
    auto up_output = at::matmul(x, up_proj.t());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_048_fused_gelu_tanh_mul_launcher(
        gate_output, up_output, output, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "bf16 Gemma3 fused gate + up projection with GELU-tanh. "
        "Three-launch chain: 2 cuBLAS at::matmul calls + 1 fused "
        "per-element GELU-tanh + bf16 multiply. hidden_size=3072, "
        "intermediate_size=24576 pinned. Destination-passing style.");
}

#include "kernel.h"

#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <ATen/cuda/CUDAContext.h>

// Fused per-element GELU-tanh + bf16 multiply kernel.
//
// Reads bf16 gate_output and up_output; for each element:
//   - upcasts gate_output to fp32
//   - computes GELU-tanh in fp32:
//       arg      = sqrt(2/pi) * (g + 0.044715 * g^3)
//       act_fp32 = 0.5 * g * (1 + tanh(arg))
//   - downcasts activated gate to bf16
//   - multiplies by bf16 up_output, writes bf16 output
//
// This matches the reference's exact dtype path
// (`activated_gate.to(gate_output.dtype) * up_output`), which is
// load-bearing for the workload tolerance band: doing the multiply
// in fp32 and casting at the end produces a value subtly different
// from the bf16-cast-then-bf16-multiply path the reference uses.

namespace {

constexpr int kBlockThreads = 256;

__global__ void __launch_bounds__(kBlockThreads, 4) k_fused_gelu_tanh_mul(
    const __nv_bfloat16* __restrict__ gate_output,
    const __nv_bfloat16* __restrict__ up_output,
    __nv_bfloat16* __restrict__ output,
    size_t total_elements
) {
    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float c = 0.044715f;

    const size_t idx_base =
        (size_t)blockIdx.x * kBlockThreads + threadIdx.x;
    const size_t stride = (size_t)gridDim.x * kBlockThreads;
    for (size_t idx = idx_base; idx < total_elements; idx += stride) {
        const float g = __bfloat162float(gate_output[idx]);
        const float g2 = g * g;
        const float g3 = g2 * g;
        const float arg = sqrt_2_over_pi * (g + c * g3);
        // Keep the tanh tail accurate even when the baseline's
        // --use_fast_math compile option is present.  The reference's
        // tolerance reaches the saturated-GELU region, where tanh.approx
        // rounds 1+tanh(arg) to zero while the FP32 reference retains a
        // small nonzero value. Evaluate tanh in double, then round to FP32
        // before the original BF16 activation/product rounding steps.
        const float t = static_cast<float>(tanh(static_cast<double>(arg)));
        const float act_fp32 = 0.5f * g * (1.0f + t);
        const __nv_bfloat16 act_bf16 = __float2bfloat16(act_fp32);
        const __nv_bfloat16 up_bf16 = up_output[idx];
        output[idx] = __hmul(act_bf16, up_bf16);
    }
}

}  // namespace

void problem_048_fused_gelu_tanh_mul_launcher(
    const torch::Tensor& gate_output,
    const torch::Tensor& up_output,
    torch::Tensor& output,
    cudaStream_t stream
) {
    const size_t total = (size_t)gate_output.numel();
    const int max_blocks = 65535;
    int blocks = static_cast<int>(
        (total + kBlockThreads - 1) / kBlockThreads);
    if (blocks > max_blocks) blocks = max_blocks;
    dim3 grid(blocks);
    dim3 block(kBlockThreads);
    k_fused_gelu_tanh_mul<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(
            gate_output.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(
            up_output.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(
            output.data_ptr<at::BFloat16>()),
        total);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "problem_048 fused GELU-tanh + multiply kernel "
                "launch failed");
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the fused per-element GELU-tanh + multiply
// portion of the Gemma3 gate + up projection chain. The two bf16
// matmuls are dispatched by main.cpp via at::matmul (cuBLAS), so
// the kernel here only handles the elementwise tail:
//
//   for each (b, s, j) in [B, S, intermediate_size]:
//     g_fp32   = (float) gate_output[b, s, j]
//     arg      = sqrt(2/pi) * (g_fp32 + 0.044715 * g_fp32^3)
//     act_fp32 = 0.5 * g_fp32 * (1 + tanh(arg))
//     act_bf16 = (bf16) act_fp32
//     output[b, s, j] = act_bf16 * up_output[b, s, j]   (bf16 product)
//
// Mirrors the PyTorch reference's exact dtype contract:
//   activated_gate = activated_gate.to(gate_output.dtype)   # to bf16
//   output         = activated_gate * up_output             # bf16 * bf16
//
// Tensors (all bf16):
//   gate_output : [B, S, intermediate_size = 24576]
//   up_output   : [B, S, intermediate_size = 24576]
//   output      : [B, S, intermediate_size = 24576] (DPS;
//                 pre-allocated by the eval driver)
//
// `intermediate_size = 24576` is pinned by the problem definition;
// `batch_size` and `seq_len` vary.
void problem_048_fused_gelu_tanh_mul_launcher(
    const torch::Tensor& gate_output,
    const torch::Tensor& up_output,
    torch::Tensor& output,
    cudaStream_t stream);
